import { JustAVPS } from '@justavps/sdk';

const client = new JustAVPS({ apiKey: 'sk_live_YOUR_KEY' });

const { machines } = await client.machines.list();
console.log(machines);

import { JustAVPS } from '@justavps/sdk';

const client = new JustAVPS({ apiKey: 'sk_live_YOUR_KEY' });

const machine = await client.machines.create({
  provider: 'hetzner',
  server_type: 'cpx22',
  region: 'nbg1',
  name: 'my-machine',
});

// Wait for it to be ready
const ready = await client.machines.waitForReady(machine.id);
console.log('Ready:', ready.connect?.vscode_url);

import { JustAVPS } from '@justavps/sdk';

const client = new JustAVPS({ apiKey: 'sk_live_YOUR_KEY' });

const machine = await client.machines.get('machine-uuid');
console.log(machine.status, machine.connect?.vscode_url);

import { JustAVPS } from '@justavps/sdk';

const client = new JustAVPS({ apiKey: 'sk_live_YOUR_KEY' });

await client.machines.delete('machine-uuid');

import { JustAVPS } from '@justavps/sdk';

const client = new JustAVPS({ apiKey: 'sk_live_YOUR_KEY' });

const result = await client.machines.reboot('machine-uuid');
console.log(result.status); // 'initiated'

import { JustAVPS } from '@justavps/sdk';

const client = new JustAVPS({ apiKey: 'sk_live_YOUR_KEY' });

const result = await client.machines.resize('machine-uuid', {
  server_type: 'cpx32',
});
console.log(result.old_type, '→', result.new_type);

import { JustAVPS } from '@justavps/sdk';

const client = new JustAVPS({ apiKey: 'sk_live_YOUR_KEY' });

// Async iterator over SSE events
for await (const event of client.machines.stream('machine-uuid')) {
  if (event.type === 'stage') {
    console.log('Stage:', event.data.provisioning_stage);
  }
  if (event.type === 'done') break;
}

// Or use the convenience helper:
const machine = await client.machines.waitForReady('machine-uuid');

